@page "/recipes"
@page "/recipes/{Category}"

<PageTitle>Recipes - @(Category ?? "All Categories")</PageTitle>

<h1>@(Category is not null ? $"Recipes: {Category}" : "All Recipes")</h1>

@if (Category is null)
{
    <ul>
        <li><a href="recipes/pasta">Pasta</a></li>
        <li><a href="recipes/salads">Salads</a></li>
        <li><a href="recipes/desserts">Desserts</a></li>
    </ul>
}
else
{
    <div class="list-group">
        @foreach (var recipe in GetRecipesForCategory())
        {
            <a href="@($"recipe/{recipe.Id}")" class="list-group-item list-group-item-action">
                <h5>@recipe.Title</h5>
                <p class="mb-0 text-muted">@recipe.Summary</p>
            </a>
        }
    </div>
}

<a href="recipes" class="btn btn-outline-secondary mt-3">← All Categories</a>

@code {
    [Parameter]
    public string? Category { get; set; }

    private List<RecipeSummary> GetRecipesForCategory()
    {
        return Category?.ToLower() switch
        {
            "pasta" => new()
            {
                new(1, "Spaghetti Carbonara", "Classic Roman pasta with eggs, cheese, and pancetta."),
                new(2, "Penne Arrabbiata", "Spicy tomato sauce with garlic and red chili flakes."),
                new(3, "Fettuccine Alfredo", "Creamy parmesan sauce over fresh fettuccine.")
            },
            "salads" => new()
            {
                new(4, "Caesar Salad", "Crisp romaine with parmesan, croutons, and Caesar dressing."),
                new(5, "Greek Salad", "Tomatoes, cucumbers, olives, and feta with olive oil."),
                new(6, "Caprese Salad", "Fresh mozzarella, tomatoes, and basil with balsamic glaze.")
            },
            "desserts" => new()
            {
                new(7, "Tiramisu", "Espresso-soaked ladyfingers layered with mascarpone cream."),
                new(8, "Chocolate Lava Cake", "Warm chocolate cake with a molten center."),
                new(9, "Panna Cotta", "Silky Italian custard with berry compote.")
            },
            _ => new()
        };
    }

    private record RecipeSummary(int Id, string Title, string Summary);
}

@page "/recipe/{Id:int}"

<PageTitle>@recipe.Title - RecipeShare</PageTitle>

<h1>@recipe.Title</h1>
<p class="text-muted">Category: @recipe.Category</p>

<h3>Ingredients</h3>
<ul>
    @foreach (var ingredient in recipe.Ingredients)
    {
        <li>@ingredient</li>
    }
</ul>

<h3>Steps</h3>
<ol>
    @foreach (var step in recipe.Steps)
    {
        <li class="mb-2">@step</li>
    }
</ol>

<hr />
<h4>Rate this recipe</h4>
<StarRating RecipeId="Id" />

<a href="recipes/@recipe.Category?.ToLower()" class="btn btn-outline-secondary mt-3">← Back to @recipe.Category</a>

@code {
    [Parameter]
    public int Id { get; set; }

