    {
        return id switch
        {
            1 => new("Spaghetti Carbonara", "Pasta", new[] { "400g spaghetti", "200g pancetta", "4 egg yolks", "100g Pecorino Romano", "Black pepper" }, new[] { "Cook spaghetti in salted boiling water until al dente.", "Fry pancetta until crispy.", "Whisk egg yolks with grated cheese and pepper.", "Toss hot pasta with pancetta, then stir in egg mixture off heat.", "Serve immediately with extra cheese." }),
            2 => new("Penne Arrabbiata", "Pasta", new[] { "400g penne", "400g canned tomatoes", "4 cloves garlic", "2 red chilies", "Fresh parsley", "Olive oil" }, new[] { "Cook penne until al dente.", "Sauté sliced garlic and chilies in olive oil.", "Add crushed tomatoes and simmer 15 minutes.", "Toss pasta with sauce.", "Garnish with fresh parsley." }),
            3 => new("Fettuccine Alfredo", "Pasta", new[] { "400g fettuccine", "100g butter", "200g Parmigiano-Reggiano", "Salt and white pepper" }, new[] { "Cook fettuccine in salted water until al dente.", "Melt butter in a large pan over low heat.", "Add drained pasta and toss with butter.", "Remove from heat, add grated cheese gradually while tossing.", "Season and serve immediately." }),
            4 => new("Caesar Salad", "Salads", new[] { "1 head romaine lettuce", "50g parmesan shavings", "Croutons", "Caesar dressing", "Anchovy fillets (optional)" }, new[] { "Wash and chop romaine into bite-sized pieces.", "Toss lettuce with Caesar dressing.", "Top with parmesan shavings and croutons.", "Add anchovy fillets if desired.", "Serve chilled." }),
            5 => new("Greek Salad", "Salads", new[] { "4 tomatoes", "1 cucumber", "1 red onion", "200g feta cheese", "Kalamata olives", "Olive oil", "Oregano" }, new[] { "Cut tomatoes and cucumber into chunks.", "Slice red onion thinly.", "Combine vegetables in a bowl.", "Top with feta and olives.", "Drizzle with olive oil and sprinkle oregano." }),
            6 => new("Caprese Salad", "Salads", new[] { "3 large tomatoes", "250g fresh mozzarella", "Fresh basil leaves", "Balsamic glaze", "Extra virgin olive oil", "Salt" }, new[] { "Slice tomatoes and mozzarella into even rounds.", "Arrange alternating on a platter.", "Tuck basil leaves between slices.", "Drizzle with olive oil and balsamic glaze.", "Season with salt and serve." }),
            7 => new("Tiramisu", "Desserts", new[] { "6 egg yolks", "500g mascarpone", "300ml strong espresso", "200g ladyfingers", "Cocoa powder", "75g sugar" }, new[] { "Whisk egg yolks with sugar until pale and thick.", "Fold in mascarpone until smooth.", "Dip ladyfingers briefly in cooled espresso.", "Layer soaked ladyfingers and mascarpone cream in a dish.", "Refrigerate 4 hours, then dust with cocoa before serving." }),
            8 => new("Chocolate Lava Cake", "Desserts", new[] { "200g dark chocolate", "100g butter", "3 eggs", "75g sugar", "30g flour", "Butter for ramekins" }, new[] { "Preheat oven to 220°C. Butter 4 ramekins.", "Melt chocolate and butter together.", "Whisk eggs and sugar, fold into chocolate mixture.", "Stir in flour gently.", "Pour into ramekins and bake 10–12 minutes until edges are set but center is soft." }),
            9 => new("Panna Cotta", "Desserts", new[] { "500ml heavy cream", "75g sugar", "2 tsp vanilla extract", "2 sheets gelatin", "Mixed berries for topping" }, new[] { "Soak gelatin in cold water.", "Heat cream with sugar and vanilla until simmering.", "Squeeze gelatin and dissolve into warm cream.", "Pour into molds and refrigerate at least 4 hours.", "Unmold and serve with fresh berries." }),
            _ => new("Recipe Not Found", "Unknown", Array.Empty<string>(), Array.Empty<string>())
        };
    }

    private record Recipe(string Title, string? Category, string[] Ingredients, string[] Steps);
}

